import java.nio.ByteBuffer;import java.nio.file.*;import zombie.ZomboidFileSystem;import zombie.Lua.LuaManager;import zombie.SandboxOptions;import zombie.core.random.RandStandard;
public class FishingSandboxProbe { public static void main(String[] args)throws Exception {ZomboidFileSystem.instance.setCacheDir("/tmp/pz-fish-sandbox-probe");ZomboidFileSystem.instance.init();RandStandard.INSTANCE.init();LuaManager.init();SandboxOptions.instance.load(ByteBuffer.wrap(Files.readAllBytes(Path.of(args[0]))));System.out.printf("FISH_OPTION saved=%d%n",SandboxOptions.instance.fishAbundance.getValue());for(int i=1;i<=5;i++){SandboxOptions.instance.fishAbundance.setValue(i);System.out.printf("FISH_OPTION %d=%d%n",i,SandboxOptions.instance.fishAbundance.getValue());}}}
